// Loaded only in the synthetic audit extension generated by browser-safety.cjs.
// Runs actual persistence helpers against real Firefox storage APIs.
var config, serverConfig, state, reqresQueue, reqresQueueSize;
var dbStateDefaults = { number: 0, size: 0 };
var synchronousClosuresA = [],
    synchronousClosuresB = [],
    reqresAlmostDone = [];
var archivedViaSubmitHTTP = 2,
    archivedViaExportAs = 1,
    archivedIntoLS = 4;
var gotNewArchivedOrNot = false,
    gotNewBuggedOut = false,
    gotNewSyncedOrNot = false;
var wantArchiveDoneNotify = false,
    wantRetryAllUnarchived = false,
    wantSaveState = false;
var wantBroadcastSaved = false,
    wantBucketSaveAs = false;
function updateLoggable() {}
function broadcastToState() {}
function scheduleUpdateDisplay() {}
function getGoodEpisodic() {
    return 100;
}
function getQueued() {
    return reqresQueue;
}
function mergeUpdatedTabIds(a, b) {
    return b;
}
function inflateMaybe(x) {
    return x;
}

const realLS = browser.storage.local;
const realFetch = fetch;
const originalWipeMany = wipeManyFromStorage;
const originalDeleteBatch = deleteArchivedBatch;
let currentCase, injected, originals;
let active = 0,
    peak = 0,
    uploads = 0,
    storageRemoves = 0;
const unhandled = [];
addEventListener("unhandledrejection", (e) => {
    unhandled.push(String(e.reason));
    e.preventDefault();
});
function check(value, message) {
    if (!value) throw Error(message);
}
function delay(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
}
async function report(value) {
    await realFetch(AUDIT_URL + "/report", { method: "POST", body: JSON.stringify(value) });
}

async function reset(name, { idb = false, count = 16, concurrency = 4 } = {}) {
    currentCase = name;
    injected = false;
    unhandled.length = 0;
    active = peak = uploads = storageRemoves = 0;
    await realLS.clear();
    if (reqresIDB) {
        reqresIDB.close();
        await idbDelete("hoardy-safety");
    }
    reqresIDB = undefined;
    config = {
        archive: true,
        archiveSubmitHTTP: true,
        archiveExportAs: false,
        archiveSaveLS: false,
        submitHTTPConcurrency: concurrency,
        submitHTTPMemory: 32,
        submitHTTPParanoid: false,
        persistLSParanoid: false,
        preferIndexedDB: idb,
        gzipLSDumps: false,
        submitHTTPURLBase: AUDIT_URL + "/",
        root: { bucket: name },
    };
    serverConfig = {
        alive: true,
        canDump: true,
        baseURL: config.submitHTTPURLBase,
        info: { dump_wrr: "/upload" },
    };
    state = {
        dumpedUndo: 0,
        stashedUndo: 0,
        savedUndo: 0,
        stashedRedo: 0,
        stashedTotal: 0,
        savedTotal: 0,
        savedRedo: 0,
        dumpedTotal: 0,
        dumpedSize: 0,
        dumpedReal: 0,
        submittedHTTPTotal: 0,
        submittedHTTPSize: 0,
        stashedLS: { number: idb ? 0 : count, size: idb ? 0 : count * 32 },
        savedLS: { number: 0, size: 0 },
        stashedIDB: { number: idb ? count : 0, size: idb ? count * 32 : 0 },
        savedIDB: { number: 0, size: 0 },
    };
    reqresQueue = [];
    reqresQueueSize = count * 32;
    reqresBuggedOutIssueAcc = newReqresBuggedOutIssueAcc();
    reqresUnarchivedIssueAcc = newReqresUnarchivedIssueAcc();
    reqresUnstashedIssueAcc = newReqresUnstashedIssueAcc();
    synchronousClosuresA = [];
    synchronousClosuresB = [];
    reqresAlmostDone = [];
    const records = {};
    for (const name of ["dump", "stash", "save"])
        records["lsmeta-" + name] = { first: 0, next: name === "save" ? 0 : count };
    for (let id = 0; id < count; id++) {
        const l = { dumpId: id, stashId: id, inLS: !idb, dumpSize: 32, tabId: id, archived: 0 };
        const dump = new Uint8Array(32);
        dump.fill(id);
        dump[31] = 255;
        records["lsdata-dump-" + id] = { dump };
        records["lsdata-stash-" + id] = { ...l };
        reqresQueue.push([l, null]);
    }
    originals = reqresQueue.slice();
    if (idb) {
        reqresIDB = await idbOpen("hoardy-safety", 1, (db) => {
            for (const name of ["dump", "stash", "save"])
                db.createObjectStore(name, { autoIncrement: true });
        });
        await idbTransaction(reqresIDB, "readwrite", ["dump", "stash"], async (t, d, s) => {
            for (let i = 0; i < count; i++) {
                await d.put(records["lsdata-dump-" + i], i);
                await s.put(records["lsdata-stash-" + i], i);
            }
        });
    } else await realLS.set(records);
    fetch = async (...args) => {
        active++;
        uploads++;
        peak = Math.max(peak, active);
        try {
            return await realFetch(...args);
        } finally {
            active--;
        }
    };
    // Instrument the storage boundary without replacing the storage engine.
    const auditedLS = {
        get: (keys) => realLS.get(keys),
        async set(values) {
            if (name === "ls-set-failure" && !injected) {
                injected = true;
                throw Error("injected set failure");
            }
            return realLS.set(values);
        },
        async remove(keys) {
            storageRemoves++;
            if (name === "ls-remove-failure" && !injected) {
                injected = true;
                throw Error("injected remove failure");
            }
            const receipts = await (await realFetch(AUDIT_URL + "/receipts?case=" + name)).json();
            for (const key of keys) {
                const m = /^lsdata-(?:dump|stash)-(\d+)$/.exec(key);
                if (m)
                    check(
                        receipts.includes(Number(m[1])),
                        "deletion before durable test-server write: " + key,
                    );
            }
            if (name === "restart-before-remove") await stopForRestart();
            await realLS.remove(keys);
            if (name === "restart-after-remove") await stopForRestart();
        },
    };
    mkLSlotTransaction = (func) =>
        lslotTransaction(auditedLS, "readwrite", ["dump", "stash", "save"], func);
    wipeManyFromStorage = originalWipeMany;
    deleteArchivedBatch = originalDeleteBatch;
}

async function verifyConservation() {
    const remote = await (await realFetch(AUDIT_URL + "/receipts?case=" + currentCase)).json();
    const discovered = [];
    await forEachInStorage("stash", (l) => {
        discovered.push(l.dumpId);
        return true;
    });
    await forEachInStorage("save", (l) => {
        discovered.push(l.dumpId);
        return true;
    });
    const local = [];
    for (const [l] of originals) {
        const id = l.tabId;
        let record;
        if (reqresIDB)
            record = await idbTransaction(reqresIDB, "readonly", ["dump"], async (t, s) =>
                s.get(id),
            );
        else record = (await realLS.get("lsdata-dump-" + id))["lsdata-dump-" + id];
        if (record && discovered.includes(id)) {
            check(
                record.dump instanceof Uint8Array && record.dump.length === 32,
                "local payload type/length: " + id,
            );
            check(
                record.dump.every((byte, index) => byte === (index === 31 ? 255 : id)),
                "local payload bytes: " + id,
            );
            local.push(id);
        }
        check(
            remote.includes(id) || local.includes(id),
            "capture missing locally and remotely: " + id,
        );
    }
    return {
        remote: remote.length,
        local: local.length,
        peak,
        uploads,
        storageRemoves,
        stashed: config.preferIndexedDB ? state.stashedIDB.number : state.stashedLS.number,
    };
}

async function runCase(name, options, setup, verify) {
    try {
        await reset(name, options);
        if (setup) await setup();
        const result = await Promise.race([
            processArchiving().then(() => "finished"),
            delay(4000).then(() => "timeout"),
        ]);
        check(result === "finished", "archival did not settle after 4 seconds");
        const summary = await verifyConservation();
        check(active === 0, "upload escaped scheduler boundary");
        if (verify) await verify(summary);
        await report({ name, passed: true, ...summary });
    } catch (error) {
        await report({
            name,
            passed: false,
            error: String(error),
            stack: error.stack,
            unhandled: [...unhandled],
        });
    }
}

async function stopForRestart() {
    await report({ restart: true });
    await new Promise(() => {});
}
async function crashBoundary(index) {
    const names = ["restart-before-cleanup", "restart-before-remove", "restart-after-remove"];
    if (index === names.length) {
        await report({ done: true });
        return;
    }
    await reset(names[index]);
    await realLS.set({ "audit-restart": { name: currentCase, index } });
    if (index === 0) deleteArchivedBatch = stopForRestart;
    await processArchiving();
}
async function main() {
    const restart = (await realLS.get("audit-restart"))["audit-restart"];
    if (restart) {
        currentCase = restart.name;
        const discovered = [];
        await forEachInStorage("stash", (l) => {
            discovered.push(l.dumpId);
            return true;
        });
        const rows = await realLS.get(null);
        const local = Object.keys(rows)
            .filter((k) => k.startsWith("lsdata-dump-"))
            .map((k) => Number(k.slice("lsdata-dump-".length)));
        const remote = await (await realFetch(AUDIT_URL + "/receipts?case=" + currentCase)).json();
        const expected = restart.index === 2 ? 12 : 16;
        const conserved = Array.from({ length: 16 }, (_, i) => i).every(
            (i) => remote.includes(i) || (local.includes(i) && discovered.includes(i)),
        );
        await report({
            name: restart.name,
            passed: conserved && local.length === expected && remote.length === 4,
            local: local.length,
            discovered: discovered.length,
            remote: remote.length,
        });
        await crashBoundary(restart.index + 1);
        return;
    }
    await runCase("ls-success", {}, null, (r) => {
        check(r.remote === 16 && r.local === 0 && r.stashed === 0, "success counts");
        check(r.peak <= 4, "concurrency");
        check(r.storageRemoves === 4, "cleanup batch count");
    });
    await runCase("idb-success", { idb: true }, null, (r) =>
        check(r.remote === 16 && r.local === 0 && r.stashed === 0, "success counts"),
    );
    await runCase("ls-http-failure", {}, null, (r) =>
        check(r.remote === 14 && r.local === 2, "failed uploads retained"),
    );
    await runCase("idb-http-failure", { idb: true }, null, (r) =>
        check(r.remote === 14 && r.local === 2, "failed uploads retained"),
    );
    await runCase("ls-set-failure", { count: 4 }, null, (r) =>
        check(r.local === 4 && r.stashed === 4, "failed set recovery"),
    );
    await runCase("ls-remove-failure", { count: 4 }, null, (r) =>
        check(r.local === 4 && r.stashed === 4, "failed remove recovery"),
    );
    await runCase(
        "ls-mixed-methods",
        {},
        () => {
            config.archiveSaveLS = true;
        },
        (r) => check(r.local === 16 && r.peak === 1, "mixed mode must remain serial"),
    );
    await runCase(
        "ls-pause",
        {},
        () => {
            const upload = fetch;
            fetch = async (...args) => {
                const response = await upload(...args);
                config.archive = false;
                return response;
            };
        },
        (r) => {
            check(r.local === 16 && r.remote === 4, "pause conservation");
            check(reqresQueue.length === 16, "pause queue");
            check(
                reqresQueue.every((a) => a[1] === null),
                "pause payload release",
            );
        },
    );
    await runCase(
        "ls-endpoint-change",
        { count: 4 },
        () => {
            const upload = fetch;
            fetch = async (...args) => {
                const response = await upload(...args);
                serverConfig.info.dump_wrr = "/upload-new";
                return response;
            };
        },
        (r) => check(r.uploads === 8, "endpoint change must resubmit"),
    );
    await runCase(
        "idb-explicit-abort",
        { idb: true, count: 4 },
        () => {
            const actual = mkIDBTransaction;
            mkIDBTransaction = (func) => {
                mkIDBTransaction = actual;
                return idbTransaction(
                    reqresIDB,
                    "readwrite",
                    ["dump", "stash", "save"],
                    async (t, d, s, v) => {
                        await d.delete(0);
                        t.abort();
                    },
                );
            };
        },
        (r) => check(r.local === 4 && r.stashed === 4, "transaction abort recovery"),
    );
    await runCase(
        "idb-callback-throw",
        { idb: true, count: 4 },
        () => {
            const actual = mkIDBTransaction;
            mkIDBTransaction = (func) => {
                mkIDBTransaction = actual;
                return idbTransaction(
                    reqresIDB,
                    "readwrite",
                    ["dump", "stash", "save"],
                    async (t, d, s, v) => {
                        await d.delete(0);
                        throw Error("injected asynchronous callback failure");
                    },
                );
            };
        },
        async (r) => {
            await delay(20);
            check(r.local === 4 && r.stashed === 4, "callback failure recovery");
            check(unhandled.length === 0, "unhandled rejection from transaction callback");
        },
    );
    // Exit at an actual cleanup boundary, with successful requests still pending
    // local finalization. The runner kills only this disposable process group.
    await crashBoundary(0);
}
main().catch(async (error) => {
    await report({ fatal: String(error), stack: error.stack });
});
